-- Source: .local/native-communication/draft-body.sql
-- Isolated draft, not a migration. Apply schema.sql first under a dedicated managed owner.
-- Requires approved root/connection/current-authority/artifact bridge implementations.
CREATE TABLE pactwoven.native_communication_bindings(login name,environment text,lane text CHECK(lane IN('provider','review','api','admission','outbox')),PRIMARY KEY(login,environment,lane));
CREATE TABLE pactwoven.native_communication_reviews(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),environment text NOT NULL,review_id text NOT NULL,producer name NOT NULL,request jsonb NOT NULL,approval jsonb NOT NULL,UNIQUE(environment,producer,review_id));
CREATE TABLE pactwoven.native_communication_observations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),environment text NOT NULL,provenance_id text NOT NULL,producer name NOT NULL,message jsonb NOT NULL,verification jsonb NOT NULL,UNIQUE(environment,producer,provenance_id));
CREATE TABLE pactwoven.native_communication_consents(environment text,organization_id text,id text,actor_id text NOT NULL,request_key text NOT NULL,body jsonb NOT NULL,PRIMARY KEY(environment,organization_id,id),UNIQUE(environment,organization_id,actor_id,request_key));
CREATE TABLE pactwoven.native_communication_heads(environment text,organization_id text,id text,version bigint NOT NULL DEFAULT 1,state text NOT NULL DEFAULT 'active' CHECK(state IN('active','revoked')),PRIMARY KEY(environment,organization_id,id),FOREIGN KEY(environment,organization_id,id) REFERENCES pactwoven.native_communication_consents);
CREATE TABLE pactwoven.native_communication_waits(environment text,organization_id text,id text,consent_id text NOT NULL,root_id text NOT NULL,target_digest text NOT NULL,body jsonb NOT NULL,PRIMARY KEY(environment,id),FOREIGN KEY(environment,organization_id,consent_id) REFERENCES pactwoven.native_communication_consents);
CREATE UNIQUE INDEX native_communication_one_wait ON pactwoven.native_communication_waits(environment,organization_id,root_id,target_digest) WHERE body->>'state'='armed';
CREATE TABLE pactwoven.native_communication_inbox(environment text,organization_id text,identity_digest text,wait_id text NOT NULL,observation_id uuid NOT NULL REFERENCES pactwoven.native_communication_observations,receipt jsonb NOT NULL,PRIMARY KEY(environment,organization_id,identity_digest),FOREIGN KEY(environment,wait_id) REFERENCES pactwoven.native_communication_waits);
CREATE TABLE pactwoven.native_communication_outbox(id text PRIMARY KEY,environment text NOT NULL,organization_id text NOT NULL,identity_digest text NOT NULL,wait_id text NOT NULL,intent jsonb NOT NULL,UNIQUE(environment,organization_id,identity_digest),FOREIGN KEY(environment,organization_id,identity_digest) REFERENCES pactwoven.native_communication_inbox);
CREATE TABLE pactwoven.native_communication_deliveries(id text PRIMARY KEY REFERENCES pactwoven.native_communication_outbox,state text NOT NULL DEFAULT 'pending' CHECK(state IN('pending','leased','delivered','suppressed')),attempt integer NOT NULL DEFAULT 0 CHECK(attempt BETWEEN 0 AND 10),token uuid,lease_until timestamptz,available_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX native_communication_due ON pactwoven.native_communication_deliveries(available_at,id) WHERE state IN('pending','leased');
CREATE FUNCTION pactwoven.native_communication_require(v boolean,code text DEFAULT 'NC004') RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 BEGIN IF v IS DISTINCT FROM true THEN RAISE EXCEPTION USING ERRCODE=code,MESSAGE='Communication boundary denied';END IF;END $$;
CREATE FUNCTION pactwoven.native_communication_validate(v jsonb,k text) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 BEGIN PERFORM pactwoven.native_communication_require(octet_length(v::text)<=131072 AND pactwoven.native_delegation_matches(v,pactwoven.native_communication_schema(k)));END $$;
CREATE FUNCTION pactwoven.native_communication_lane(env text,lane text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 BEGIN
 PERFORM set_config('lock_timeout','2000ms',true);
 PERFORM 1 FROM pactwoven.native_communication_bindings b JOIN pg_roles r ON r.rolname=b.login WHERE b.login=SESSION_USER AND b.environment=env AND b.lane=lane AND NOT(r.rolsuper OR r.rolbypassrls OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication) FOR SHARE OF b;
 PERFORM pactwoven.native_communication_require(FOUND,'NC001');
END $$;
CREATE FUNCTION pactwoven.native_communication_bridge(k text,a jsonb,b jsonb DEFAULT 'null') RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE answer jsonb;signature text;BEGIN
 PERFORM pactwoven.native_communication_require(k IN('connection','authority','artifact','enter_wait','wake'),'NC010');signature:='pactwoven.native_communication_bridge_'||k||'(jsonb,jsonb)';
 IF to_regprocedure(signature) IS NULL THEN RAISE EXCEPTION USING ERRCODE='NC010',MESSAGE='Communication bridge is not installed';END IF;
 EXECUTE format('SELECT pactwoven.%I($1,$2)','native_communication_bridge_'||k) INTO answer USING a,b;RETURN answer;
END $$;
-- Shared lock order: real connection -> consent head -> real human/org/site/root/delegation -> wait -> inbox identity -> delivery.
CREATE FUNCTION pactwoven.native_communication_context(req jsonb,actor jsonb,head_required boolean) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable

DECLARE connection jsonb;ctx jsonb;human jsonb;root jsonb;head record;head_version bigint;t timestamptz;BEGIN
 PERFORM pactwoven.native_communication_validate(req,'request');
 connection:=pactwoven.native_communication_bridge('connection',req,actor);PERFORM pactwoven.native_communication_validate(connection,'connection');
 IF head_required THEN SELECT * INTO head FROM pactwoven.native_communication_heads WHERE(environment,organization_id,id)=(req#>>'{scope,environment}',req#>>'{scope,organizationId}',req->>'id') FOR UPDATE;PERFORM pactwoven.native_communication_require(FOUND AND head.state='active','NC001');head_version:=head.version;END IF;
 ctx:=pactwoven.native_communication_bridge('authority',req,actor);human:=ctx->'authority';root:=ctx->'root';
 PERFORM pactwoven.native_communication_validate(human,'authority');PERFORM pactwoven.native_communication_validate(root,'root');t:=clock_timestamp();
 PERFORM pactwoven.native_communication_require(connection->>'status'='connected' AND human->>'state'='current','NC001');
 PERFORM pactwoven.native_communication_require((connection->>'observedAt')::timestamptz<=t AND(connection->>'validUntil')::timestamptz>t AND(connection->>'validUntil')::timestamptz-(connection->>'observedAt')::timestamptz<=interval '20 seconds' AND(human->>'observedAt')::timestamptz<=t AND(human->>'validUntil')::timestamptz>t AND(human->>'validUntil')::timestamptz-(human->>'observedAt')::timestamptz<=interval '20 seconds','NC008');
 PERFORM pactwoven.native_communication_require(connection->>'id'=req->>'connectionId' AND connection->'version'=req->'connectionVersion' AND connection->>'accountSubject'=req->>'accountSubject' AND connection->>'actorId'=req->>'actorId' AND connection->>'environment'=req#>>'{scope,environment}' AND connection->>'organizationId'=req#>>'{scope,organizationId}' AND human->'scope'=req->'scope' AND human->>'actorId'=req->>'actorId' AND human->'membershipVersion'=req->'membershipVersion' AND human->'organizationEpoch'=req->'organizationEpoch' AND root->'scope'=req->'scope' AND root->>'actorId'=req->>'actorId' AND root->>'rootTaskId'=req->>'rootTaskId' AND root->'authority'=req->'rootAuthority','NC001');
 PERFORM pactwoven.native_communication_require(connection->'oauthScopes' ? CASE req#>>'{target,kind}' WHEN 'gmail_reply' THEN 'https://www.googleapis.com/auth/gmail.readonly' ELSE 'https://www.googleapis.com/auth/calendar.events.readonly' END,'NC001');
 IF actor<>'null'::jsonb THEN PERFORM pactwoven.native_communication_require(actor->>'principalKind'='human' AND actor->>'actorId'=req->>'actorId' AND actor->>'environment'=req#>>'{scope,environment}' AND actor->>'organizationId'=req#>>'{scope,organizationId}' AND actor->'actionSiteIds' ? (req#>>'{scope,siteId}'),'NC001');END IF;
 PERFORM pactwoven.native_communication_require((req->>'expiresAt')::timestamptz>t,'NC002');
 RETURN jsonb_build_object('connection',connection,'authority',human,'root',root,'headVersion',head_version);
END $$;
-- Recheck cached observations after every lock/bridge wait, including after transactional effects.
CREATE FUNCTION pactwoven.native_communication_context_fresh(ctx jsonb,req jsonb) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE t timestamptz:=clock_timestamp();BEGIN
 PERFORM pactwoven.native_communication_require((ctx#>>'{connection,observedAt}')::timestamptz<=t AND(ctx#>>'{connection,validUntil}')::timestamptz>t AND(ctx#>>'{authority,observedAt}')::timestamptz<=t AND(ctx#>>'{authority,validUntil}')::timestamptz>t,'NC008');
 PERFORM pactwoven.native_communication_require((req->>'expiresAt')::timestamptz>t,'NC002');
END $$;
-- Retained proof is evidence, not continuing enrollment. Hold its current producer row through commit.
CREATE FUNCTION pactwoven.native_communication_producer_current(env text,producer name,lane text) RETURNS void LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 BEGIN
 PERFORM 1 FROM pactwoven.native_communication_bindings b JOIN pg_roles r ON r.rolname=b.login WHERE b.login=producer AND b.environment=env AND b.lane=lane AND NOT(r.rolsuper OR r.rolbypassrls OR r.rolcreatedb OR r.rolcreaterole OR r.rolreplication) FOR SHARE OF b;
 PERFORM pactwoven.native_communication_require(FOUND,'NC001');
END $$;
CREATE FUNCTION pactwoven.native_communication_retain_review(env text,review_id text,req jsonb,approval jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE old record;answer uuid;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'review');PERFORM pactwoven.native_communication_validate(req,'request');PERFORM pactwoven.native_communication_validate(approval,'approval');PERFORM pactwoven.native_communication_require(req#>>'{scope,environment}'=env AND length(review_id) BETWEEN 1 AND 128);
 INSERT INTO pactwoven.native_communication_reviews(environment,review_id,producer,request,approval) VALUES(env,review_id,SESSION_USER,req,approval) ON CONFLICT DO NOTHING RETURNING id INTO answer;
 IF answer IS NULL THEN SELECT * INTO old FROM pactwoven.native_communication_reviews r WHERE r.environment=env AND r.review_id=review_id AND producer=SESSION_USER;PERFORM pactwoven.native_communication_require(old.request=req AND old.approval=approval,'NC003');answer:=old.id;END IF;RETURN answer;
END $$;
CREATE FUNCTION pactwoven.native_communication_retain_observation(env text,provenance_id text,message jsonb,verification jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE old record;answer uuid;identity text;source jsonb;t timestamptz:=clock_timestamp();BEGIN
 PERFORM pactwoven.native_communication_lane(env,'provider');PERFORM pactwoven.native_communication_validate(message,'message');PERFORM pactwoven.native_communication_validate(verification,'verification');source:=message->'source';
 PERFORM pactwoven.native_communication_require((message->'content'='null'::jsonb AND source->>'kind'='calendar_change' AND source->>'change'='deleted') OR(message->'content'<>'null'::jsonb AND message#>'{content,scope}'=message->'scope' AND NOT(source->>'kind'='calendar_change' AND source->>'change'='deleted')));
 identity:=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/incoming-identity/v1','environment',message#>>'{scope,environment}','organizationId',message#>>'{scope,organizationId}','connectionId',message->>'connectionId','accountSubject',message->>'accountSubject','identity',CASE source->>'kind' WHEN 'gmail_reply' THEN jsonb_build_object('kind','gmail_reply','messageId',source->>'messageId') ELSE jsonb_build_object('kind','calendar_change','calendarId',source->>'calendarId','eventId',source->>'eventId','etag',source->>'etag') END));
 PERFORM pactwoven.native_communication_require(message#>>'{scope,environment}'=env AND verification->>'identityDigest'=identity AND verification->>'messageDigest'=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/incoming-message/v1','message',message)) AND verification->>'connectionId'=message->>'connectionId' AND verification->'connectionVersion'=message->'connectionVersion' AND verification->>'accountSubject'=message->>'accountSubject','NC001');
 PERFORM pactwoven.native_communication_require((verification->>'observedAt')::timestamptz<=t AND(verification->>'validUntil')::timestamptz>t AND(verification->>'validUntil')::timestamptz-(verification->>'observedAt')::timestamptz<=interval '20 seconds','NC008');
 INSERT INTO pactwoven.native_communication_observations(environment,provenance_id,producer,message,verification) VALUES(env,provenance_id,SESSION_USER,message,verification) ON CONFLICT DO NOTHING RETURNING id INTO answer;
 IF answer IS NULL THEN SELECT * INTO old FROM pactwoven.native_communication_observations o WHERE o.environment=env AND o.provenance_id=provenance_id AND producer=SESSION_USER;PERFORM pactwoven.native_communication_require(old.message=message AND old.verification=verification,'NC003');answer:=old.id;END IF;RETURN answer;
END $$;
CREATE FUNCTION pactwoven.native_communication_issue(env text,actor jsonb,proof uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE p record;old record;ctx jsonb;req jsonb;a jsonb;digest text;answer jsonb;t timestamptz;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'api');SELECT * INTO p FROM pactwoven.native_communication_reviews WHERE id=proof AND environment=env;PERFORM pactwoven.native_communication_require(FOUND,'NC001');req:=p.request;a:=p.approval;
 ctx:=pactwoven.native_communication_context(req,actor,false);digest:=pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/channel-read-consent/v1','request',req));
 PERFORM pg_advisory_xact_lock(hashtextextended(env||':'||(req#>>'{scope,organizationId}')||':'||(req->>'actorId')||':'||(req->>'requestKey'),0));
 SELECT * INTO old FROM pactwoven.native_communication_consents WHERE(environment,organization_id,actor_id,request_key)=(env,req#>>'{scope,organizationId}',req->>'actorId',req->>'requestKey');
 PERFORM pactwoven.native_communication_context_fresh(ctx,req);
 IF old.id IS NOT NULL THEN PERFORM pactwoven.native_communication_require(old.body->'request'=req AND old.body->>'digest'=digest,'NC003');RETURN old.body;END IF;
 PERFORM pactwoven.native_communication_producer_current(env,p.producer,'review');PERFORM pactwoven.native_communication_context_fresh(ctx,req);
 t:=clock_timestamp();PERFORM pactwoven.native_communication_require(((a->'actor')-'correlationId')=(actor-'correlationId') AND a->>'reviewDigest'=digest AND actor->'roles' ?| ARRAY['owner','operations'] AND(a->>'confirmedAt')::timestamptz<=t AND(a->>'confirmedAt')::timestamptz>=t-interval '5 minutes' AND(a->>'sessionVerifiedAt')::timestamptz BETWEEN(a->>'confirmedAt')::timestamptz AND t AND(a->>'sessionVerifiedAt')::timestamptz>=t-interval '20 seconds' AND(a->>'sessionExpiresAt')::timestamptz>t AND(actor->>'authenticatedAt')::timestamptz<=(a->>'confirmedAt')::timestamptz,'NC001');
 PERFORM pactwoven.native_communication_require(ctx#>>'{root,state}' IN('ready','running','waiting_external') AND(req->>'expiresAt')::timestamptz<=(ctx#>>'{root,expiresAt}')::timestamptz AND(req->>'expiresAt')::timestamptz<=t+interval '24 hours','NC002');
 answer:=jsonb_build_object('schemaVersion',1,'request',req,'digest',digest,'issuedAt',pactwoven.native_memory_instant(t),'approval',jsonb_build_object('sessionId',actor->>'sessionId','authenticatedAt',actor->>'authenticatedAt','confirmedAt',a->>'confirmedAt'));PERFORM pactwoven.native_communication_validate(answer,'consent');
 INSERT INTO pactwoven.native_communication_consents VALUES(env,req#>>'{scope,organizationId}',req->>'id',req->>'actorId',req->>'requestKey',answer);INSERT INTO pactwoven.native_communication_heads(environment,organization_id,id) VALUES(env,req#>>'{scope,organizationId}',req->>'id');PERFORM pactwoven.native_communication_context_fresh(ctx,req);RETURN answer;
END $$;
CREATE FUNCTION pactwoven.native_communication_arm(env text,actor jsonb,consent_id text,wait_id text,deadline text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE c record;w record;ctx jsonb;root jsonb;answer jsonb;t timestamptz;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'api');SELECT * INTO c FROM pactwoven.native_communication_consents WHERE(environment,organization_id,id)=(env,actor->>'organizationId',consent_id);PERFORM pactwoven.native_communication_require(FOUND,'NC001');ctx:=pactwoven.native_communication_context(c.body->'request',actor,true);
 SELECT * INTO w FROM pactwoven.native_communication_waits WHERE environment=env AND id=wait_id FOR UPDATE;
 PERFORM pactwoven.native_communication_context_fresh(ctx,c.body->'request');
 IF w.id IS NOT NULL THEN PERFORM pactwoven.native_communication_require(w.consent_id=consent_id AND w.organization_id=actor->>'organizationId' AND w.body->>'expiresAt'=deadline,'NC003');RETURN w.body;END IF;
 root:=pactwoven.native_communication_bridge('enter_wait',c.body->'request',jsonb_build_object('actor',actor,'root',ctx->'root','waitId',wait_id));PERFORM pactwoven.native_communication_validate(root,'root');PERFORM pactwoven.native_communication_context_fresh(ctx,c.body->'request');t:=clock_timestamp();
 PERFORM pactwoven.native_communication_require(root->'scope'=c.body#>'{request,scope}' AND root->>'rootTaskId'=c.body#>>'{request,rootTaskId}' AND root->'authority'=c.body#>'{request,rootAuthority}' AND root->>'state'='waiting_external' AND deadline::timestamptz>t AND deadline::timestamptz<=(root->>'expiresAt')::timestamptz AND deadline::timestamptz<=(c.body#>>'{request,expiresAt}')::timestamptz,'NC005');
 answer:=jsonb_build_object('id',wait_id,'version',1,'scope',root->'scope','rootTaskId',root->>'rootTaskId','rootAuthority',root->'authority','rootGeneration',root->'generation','rootControlVersion',root->'controlVersion','consentId',consent_id,'consentDigest',c.body->>'digest','consentVersion',ctx->'headVersion','armedAt',pactwoven.native_memory_instant(t),'expiresAt',deadline,'state','armed');PERFORM pactwoven.native_communication_validate(answer,'wait');
 INSERT INTO pactwoven.native_communication_waits VALUES(env,c.organization_id,wait_id,consent_id,root->>'rootTaskId',pactwoven.native_delegation_hash(c.body#>'{request,target}'),answer);PERFORM pactwoven.native_communication_context_fresh(ctx,c.body->'request');RETURN answer;
END $$;
CREATE FUNCTION pactwoven.native_communication_revoke(env text,actor jsonb,consent_id text,expected bigint) RETURNS bigint LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE c record;v bigint;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'api');SELECT * INTO c FROM pactwoven.native_communication_consents WHERE(environment,organization_id,id)=(env,actor->>'organizationId',consent_id);PERFORM pactwoven.native_communication_require(FOUND,'NC001');PERFORM pactwoven.native_communication_context(c.body->'request',actor,true);
 UPDATE pactwoven.native_communication_heads SET state='revoked',version=version+1 WHERE(environment,organization_id,id)=(env,c.organization_id,consent_id) AND version=expected AND state='active' RETURNING version INTO v;PERFORM pactwoven.native_communication_require(FOUND,'NC005');RETURN v;
END $$;
CREATE FUNCTION pactwoven.native_communication_admit(env text,proof uuid,wait_id text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable

DECLARE w record;c record;p record;old record;ctx jsonb;req jsonb;m jsonb;v jsonb;src jsonb;target jsonb;root jsonb;receipt jsonb;wake jsonb;identity text;reason text:='correlated';t timestamptz;version bigint;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'admission');
 SELECT * INTO w FROM pactwoven.native_communication_waits WHERE environment=env AND id=wait_id;PERFORM pactwoven.native_communication_require(FOUND,'NC001');
 SELECT * INTO c FROM pactwoven.native_communication_consents WHERE(environment,organization_id,id)=(env,w.organization_id,w.consent_id);req:=c.body->'request';
 ctx:=pactwoven.native_communication_context(req,'null',true);root:=ctx->'root';
 SELECT * INTO w FROM pactwoven.native_communication_waits WHERE environment=env AND id=wait_id FOR UPDATE;
 SELECT * INTO p FROM pactwoven.native_communication_observations WHERE environment=env AND id=proof;PERFORM pactwoven.native_communication_require(FOUND,'NC001');m:=p.message;v:=p.verification;src:=m->'source';target:=req->'target';identity:=v->>'identityDigest';t:=clock_timestamp();
 PERFORM pactwoven.native_communication_producer_current(env,p.producer,'provider');
 PERFORM pactwoven.native_communication_require((v->>'observedAt')::timestamptz<=t AND(v->>'validUntil')::timestamptz>t AND(m->>'occurredAt')::timestamptz<=t,'NC008');
 PERFORM pactwoven.native_communication_require(m->'scope'=req->'scope' AND m->>'connectionId'=req->>'connectionId' AND m->'connectionVersion'=req->'connectionVersion' AND m->>'accountSubject'=req->>'accountSubject' AND w.body->'scope'=req->'scope' AND w.body->>'rootTaskId'=req->>'rootTaskId' AND w.body->'rootAuthority'=req->'rootAuthority' AND w.body->>'consentDigest'=c.body->>'digest' AND w.body->'consentVersion'=ctx->'headVersion' AND(w.body->>'armedAt')::timestamptz>=(c.body->>'issuedAt')::timestamptz AND(w.body->>'expiresAt')::timestamptz<=(req->>'expiresAt')::timestamptz AND(w.body->>'expiresAt')::timestamptz<=(root->>'expiresAt')::timestamptz,'NC001');
 IF m->'content'<>'null'::jsonb THEN PERFORM pactwoven.native_communication_require(m#>'{content,scope}'=req->'scope' AND pactwoven.native_communication_bridge('artifact',req,m->'content')=m->'content','NC001');ELSE PERFORM pactwoven.native_communication_require(src->>'kind'='calendar_change' AND src->>'change'='deleted');END IF;
 PERFORM pactwoven.native_communication_require(src->>'kind'=target->>'kind','NC001');
 IF src->>'kind'='gmail_reply' THEN PERFORM pactwoven.native_communication_require(src->>'threadId'=target->>'threadId' AND src->>'parentMessageId'=target->>'parentMessageId' AND src->>'messageId'<>src->>'parentMessageId' AND src->>'replyTokenHash'=target->>'replyTokenHash' AND src->>'sender'=v->>'authenticatedSender' AND target->'allowedSenders' ? (src->>'sender'),'NC001');
 ELSE PERFORM pactwoven.native_communication_require(src->>'calendarId'=target->>'calendarId' AND src->>'eventId'=target->>'eventId' AND src->>'etag'<>src->>'previousEtag' AND v->'authenticatedSender'='null'::jsonb,'NC001');END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(identity,0));
 SELECT * INTO old FROM pactwoven.native_communication_inbox WHERE(environment,organization_id,identity_digest)=(env,w.organization_id,identity);
 PERFORM pactwoven.native_communication_context_fresh(ctx,req);
 IF old.identity_digest IS NOT NULL THEN PERFORM pactwoven.native_communication_require(old.receipt->>'messageDigest'=v->>'messageDigest' AND old.receipt->'scope'=m->'scope' AND old.receipt->>'waitId'=wait_id AND old.receipt->>'rootTaskId'=w.body->>'rootTaskId','NC003');RETURN old.receipt;END IF;
 IF(m->>'occurredAt')::timestamptz<(w.body->>'armedAt')::timestamptz THEN reason:='before_wait';
 ELSIF(w.body->>'expiresAt')::timestamptz<=t THEN reason:='wait_expired';ELSIF w.body->>'state'<>'armed' THEN reason:='wait_closed';ELSIF root->>'state'<>'waiting_external' THEN reason:='root_stopped';
 ELSIF root->'generation'<>w.body->'rootGeneration' OR root->'controlVersion'<>w.body->'rootControlVersion' OR(root->>'expiresAt')::timestamptz<=t THEN reason:='root_changed';
 ELSIF src->>'kind'='calendar_change' AND src->>'previousEtag'<>target->>'expectedEtag' THEN reason:='calendar_changed';END IF;
 version:=(w.body->>'version')::bigint;
 IF reason='correlated' THEN wake:=jsonb_build_object('schemaVersion',1,'id',pactwoven.native_delegation_hash(jsonb_build_object('namespace','pactwoven/reply-wake/v1','identityDigest',identity,'waitId',wait_id,'waitVersion',version)),'scope',w.body->'scope','rootTaskId',w.body->>'rootTaskId','rootGeneration',w.body->'rootGeneration','rootControlVersion',w.body->'rootControlVersion','rootAuthority',w.body->'rootAuthority','waitId',wait_id,'expectedWaitVersion',version,'inboxIdentity',identity,'reason','correlated_inbound','permission','recheck_only','outboundEffects','forbidden');PERFORM pactwoven.native_communication_validate(wake,'wake');END IF;
 t:=clock_timestamp();PERFORM pactwoven.native_communication_require((v->>'validUntil')::timestamptz>t AND(ctx#>>'{connection,validUntil}')::timestamptz>t AND(ctx#>>'{authority,validUntil}')::timestamptz>t AND(req->>'expiresAt')::timestamptz>t AND(wake IS NULL OR((w.body->>'expiresAt')::timestamptz>t AND(root->>'expiresAt')::timestamptz>t)),'NC008');
 receipt:=jsonb_build_object('schemaVersion',1,'identityDigest',identity,'messageDigest',v->>'messageDigest','scope',m->'scope','connectionId',m->>'connectionId','accountSubject',m->>'accountSubject','waitId',wait_id,'waitVersion',version,'rootTaskId',w.body->>'rootTaskId','admittedAt',pactwoven.native_memory_instant(t),'disposition',CASE WHEN wake IS NULL THEN 'ignored' ELSE 'wake_planned' END,'reason',reason,'wake',wake);PERFORM pactwoven.native_communication_validate(receipt,'receipt');
 INSERT INTO pactwoven.native_communication_inbox VALUES(env,w.organization_id,identity,wait_id,proof,receipt);
 IF wake IS NOT NULL THEN
  UPDATE pactwoven.native_communication_waits SET body=jsonb_set(jsonb_set(body,'{version}',to_jsonb(version+1)),'{state}','"satisfied"') WHERE environment=env AND id=wait_id AND body=w.body AND body->>'state'='armed';PERFORM pactwoven.native_communication_require(FOUND,'NC005');
  INSERT INTO pactwoven.native_communication_outbox VALUES(wake->>'id',env,w.organization_id,identity,wait_id,wake);INSERT INTO pactwoven.native_communication_deliveries(id) VALUES(wake->>'id');
 END IF;PERFORM pactwoven.native_communication_context_fresh(ctx,req);PERFORM pactwoven.native_communication_require((v->>'validUntil')::timestamptz>clock_timestamp(),'NC008');RETURN receipt;
END $$;
CREATE FUNCTION pactwoven.native_communication_recover(env text,actor jsonb,identity text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE old record;w record;c record;p record;ctx jsonb;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'api');SELECT * INTO old FROM pactwoven.native_communication_inbox WHERE(environment,organization_id,identity_digest)=(env,actor->>'organizationId',identity);IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO w FROM pactwoven.native_communication_waits WHERE environment=env AND id=old.wait_id;SELECT * INTO c FROM pactwoven.native_communication_consents WHERE(environment,organization_id,id)=(env,w.organization_id,w.consent_id);
 ctx:=pactwoven.native_communication_context(c.body->'request',actor,true);SELECT * INTO p FROM pactwoven.native_communication_observations WHERE id=old.observation_id;
 IF p.message->'content'<>'null'::jsonb THEN PERFORM pactwoven.native_communication_require(pactwoven.native_communication_bridge('artifact',c.body->'request',p.message->'content')=p.message->'content','NC001');END IF;PERFORM pactwoven.native_communication_context_fresh(ctx,c.body->'request');RETURN old.receipt;
END $$;
-- Locks the same original scope before touching delivery state. It never transitions a root.
CREATE FUNCTION pactwoven.native_communication_wake_context(intent jsonb) RETURNS jsonb LANGUAGE plpgsql SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE w record;c record;ctx jsonb;p record;root jsonb;BEGIN
 PERFORM pactwoven.native_communication_validate(intent,'wake');SELECT * INTO w FROM pactwoven.native_communication_waits WHERE environment=intent#>>'{scope,environment}' AND id=intent->>'waitId';PERFORM pactwoven.native_communication_require(FOUND,'NC001');
 SELECT * INTO c FROM pactwoven.native_communication_consents WHERE(environment,organization_id,id)=(w.environment,w.organization_id,w.consent_id);ctx:=pactwoven.native_communication_context(c.body->'request','null',true);root:=ctx->'root';
 SELECT * INTO w FROM pactwoven.native_communication_waits WHERE environment=intent#>>'{scope,environment}' AND id=intent->>'waitId' FOR UPDATE;
 PERFORM pactwoven.native_communication_require(w.body->'scope'=intent->'scope' AND w.body->>'rootTaskId'=intent->>'rootTaskId' AND w.body->'rootAuthority'=intent->'rootAuthority','NC001');
 SELECT p0.* INTO p FROM pactwoven.native_communication_inbox i JOIN pactwoven.native_communication_observations p0 ON p0.id=i.observation_id WHERE(i.environment,i.organization_id,i.identity_digest)=(w.environment,w.organization_id,intent->>'inboxIdentity');PERFORM pactwoven.native_communication_require(FOUND,'NC001');
 IF p.message->'content'<>'null'::jsonb THEN PERFORM pactwoven.native_communication_require(pactwoven.native_communication_bridge('artifact',c.body->'request',p.message->'content')=p.message->'content','NC001');END IF;
 PERFORM pactwoven.native_communication_context_fresh(ctx,c.body->'request');
 RETURN jsonb_build_object('request',c.body->'request','eligible',root->>'state'='waiting_external' AND root->'generation'=intent->'rootGeneration' AND root->'controlVersion'=intent->'rootControlVersion' AND root->'authority'=intent->'rootAuthority' AND(root->>'expiresAt')::timestamptz>clock_timestamp() AND w.body->>'state'='satisfied' AND(w.body->>'version')::bigint=(intent->>'expectedWaitVersion')::bigint+1 AND w.body->'consentVersion'=ctx->'headVersion','context',ctx);
END $$;
CREATE FUNCTION pactwoven.native_communication_claim(env text,requested integer,lease_ms integer) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE candidate record;d record;ctx jsonb;answer jsonb:='[]';token uuid;deadline timestamptz;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'outbox');PERFORM pactwoven.native_communication_require(requested BETWEEN 1 AND 20 AND lease_ms BETWEEN 1000 AND 30000);
 FOR candidate IN SELECT o.* FROM pactwoven.native_communication_outbox o JOIN pactwoven.native_communication_deliveries d0 ON d0.id=o.id WHERE o.environment=env AND d0.state IN('pending','leased') AND d0.available_at<=clock_timestamp() AND(d0.state='pending' OR d0.lease_until<=clock_timestamp()) ORDER BY d0.available_at,o.id LIMIT 20 LOOP
  BEGIN ctx:=pactwoven.native_communication_wake_context(candidate.intent);
  EXCEPTION WHEN SQLSTATE 'NC008' THEN UPDATE pactwoven.native_communication_deliveries SET available_at=clock_timestamp()+interval '5 seconds' WHERE id=candidate.id AND state IN('pending','leased');CONTINUE;
  WHEN SQLSTATE 'NC001' OR SQLSTATE 'NC002' THEN UPDATE pactwoven.native_communication_deliveries SET state='suppressed',token=NULL,lease_until=NULL WHERE id=candidate.id AND state IN('pending','leased');CONTINUE;END;
  SELECT * INTO d FROM pactwoven.native_communication_deliveries WHERE id=candidate.id FOR UPDATE SKIP LOCKED;IF NOT FOUND OR d.state NOT IN('pending','leased') OR(d.state='leased' AND d.lease_until>clock_timestamp()) THEN CONTINUE;END IF;
  IF NOT(ctx->>'eligible')::boolean OR d.attempt>=10 THEN UPDATE pactwoven.native_communication_deliveries SET state='suppressed',token=NULL,lease_until=NULL WHERE id=candidate.id;CONTINUE;END IF;
  PERFORM pactwoven.native_communication_context_fresh(ctx->'context',ctx->'request');PERFORM pactwoven.native_communication_require((ctx#>>'{context,root,expiresAt}')::timestamptz>clock_timestamp(),'NC008');
  token:=gen_random_uuid();deadline:=clock_timestamp()+make_interval(secs=>lease_ms/1000.0);UPDATE pactwoven.native_communication_deliveries SET state='leased',attempt=attempt+1,token=token,lease_until=deadline WHERE id=candidate.id;
  answer:=answer||jsonb_build_array(jsonb_build_object('intent',candidate.intent,'token',token,'attempt',d.attempt+1,'expiresAt',pactwoven.native_memory_instant(deadline)));EXIT WHEN jsonb_array_length(answer)>=requested;
 END LOOP;RETURN answer;
END $$;
CREATE FUNCTION pactwoven.native_communication_deliver(env text,wake_id text,lease_token uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog AS $$
#variable_conflict use_variable
 DECLARE o record;d record;ctx jsonb;result jsonb;state text;BEGIN
 PERFORM pactwoven.native_communication_lane(env,'outbox');SELECT * INTO o FROM pactwoven.native_communication_outbox WHERE environment=env AND id=wake_id;PERFORM pactwoven.native_communication_require(FOUND,'NC001');
 BEGIN ctx:=pactwoven.native_communication_wake_context(o.intent);EXCEPTION WHEN SQLSTATE 'NC001' OR SQLSTATE 'NC002' THEN ctx:=jsonb_build_object('eligible',false);END;
 SELECT * INTO d FROM pactwoven.native_communication_deliveries WHERE id=wake_id FOR UPDATE;
 IF d.state='suppressed' THEN state:='suppressed';ELSIF d.state='delivered' AND d.token=lease_token THEN state:='delivered';
 ELSIF d.state<>'leased' OR d.token IS DISTINCT FROM lease_token OR d.lease_until<=clock_timestamp() THEN state:='lease_lost';
 ELSIF NOT(ctx->>'eligible')::boolean THEN state:='suppressed';UPDATE pactwoven.native_communication_deliveries SET state='suppressed' WHERE id=wake_id;
 ELSE
  PERFORM pactwoven.native_communication_context_fresh(ctx->'context',ctx->'request');PERFORM pactwoven.native_communication_require((ctx#>>'{context,root,expiresAt}')::timestamptz>clock_timestamp(),'NC008');
  result:=pactwoven.native_communication_bridge('wake',o.intent,ctx->'context');PERFORM pactwoven.native_communication_require(result->>'id'=wake_id AND result->>'rootTaskId'=o.intent->>'rootTaskId' AND result->>'status' IN('queued','suppressed'),'NC010');
  state:=CASE result->>'status' WHEN 'queued' THEN 'delivered' ELSE 'suppressed' END;UPDATE pactwoven.native_communication_deliveries SET state=state WHERE id=wake_id;
  PERFORM pactwoven.native_communication_context_fresh(ctx->'context',ctx->'request');PERFORM pactwoven.native_communication_require((ctx#>>'{context,root,expiresAt}')::timestamptz>clock_timestamp() AND d.lease_until>clock_timestamp(),'NC008');
 END IF;RETURN jsonb_build_object('id',wake_id,'status',state);
END $$;
-- Only the managed owner can access raw records. Enrollment and routine grants are explicit deployment work.
DO $$ DECLARE row record;BEGIN
 FOR row IN SELECT c.relname FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='pactwoven' AND c.relkind='r' AND c.relname LIKE 'native_communication_%' LOOP
  EXECUTE format('REVOKE ALL ON TABLE pactwoven.%I FROM PUBLIC',row.relname);EXECUTE format('ALTER TABLE pactwoven.%I ENABLE ROW LEVEL SECURITY',row.relname);EXECUTE format('ALTER TABLE pactwoven.%I FORCE ROW LEVEL SECURITY',row.relname);EXECUTE format('CREATE POLICY owner_access ON pactwoven.%I TO %I USING(true) WITH CHECK(true)',row.relname,CURRENT_USER);
 END LOOP;
 FOR row IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='pactwoven' AND p.proname LIKE 'native_communication_%' LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',row.signature);END LOOP;
END $$;
DO $$ DECLARE t record;f record;BEGIN
 FOR t IN SELECT c.oid::regclass relation,c.relname FROM pg_class c WHERE c.relnamespace='pactwoven'::regnamespace AND c.relkind='r' AND (c.relname LIKE 'native_communication_%') LOOP
  EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY',t.relation);EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY',t.relation);
  EXECUTE format('REVOKE ALL ON TABLE %s FROM PUBLIC',t.relation);
  IF NOT EXISTS(SELECT 1 FROM pg_policy WHERE polrelid=t.relation AND polname='google_production_owner') THEN EXECUTE format('CREATE POLICY google_production_owner ON %s TO %I USING(true) WITH CHECK(true)',t.relation,CURRENT_USER);END IF;
 END LOOP;
 FOR f IN SELECT oid::regprocedure signature FROM pg_proc WHERE pronamespace='pactwoven'::regnamespace AND (proname LIKE 'native_communication_%') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC',f.signature);END LOOP;
END $$;
COMMIT;
